export function graphql(source: "subscription ZC_RecordHistoryLive($filter: RecordFilter) {\n  records(first: 25, filter: $filter, orderBy: [DATE_CREATED_DESC, ID_DESC]) {\n    edges {\n      cursor\n      node {\n        ...ZC_RecordHistoryRow\n      }\n    }\n    pageInfo {\n      startCursor\n      endCursor\n      hasNextPage\n      hasPreviousPage\n    }\n    totalCount\n  }\n}"): (typeof documents)["subscription ZC_RecordHistoryLive($filter: RecordFilter) {\n  records(first: 25, filter: $filter, orderBy: [DATE_CREATED_DESC, ID_DESC]) {\n    edges {\n      cursor\n      node {\n        ...ZC_RecordHistoryRow\n      }\n    }\n    pageInfo {\n      startCursor\n      endCursor\n      hasNextPage\n      hasPreviousPage\n    }\n    totalCount\n  }\n}"];

export function graphql(source: string) {
  return (documents as any)[source] ?? {};
}

export type DocumentType<TDocumentNode extends DocumentNode<any, any>> = TDocumentNode extends DocumentNode<  infer TType,  any>  ? TType  : never;